// swift-tools-version:6.2
import PackageDescription

let debugWarningFlags: [SwiftSetting] = [
    .unsafeFlags(
        [
            "-Xfrontend", "-warn-long-function-bodies=100",
            "-Xfrontend", "-warn-long-expression-type-checking=100",
        ],
        .when(configuration: .debug)
    ),
]

let sharedSwiftSettings: [SwiftSetting] = [
    .enableExperimentalFeature("StrictConcurrency"),
    .unsafeFlags(["-strict-concurrency=complete"]),
] + debugWarningFlags

let package = Package(
    name: "RecordML",
    platforms: [
        .macOS(.v15),
    ],
    products: [
        .library(name: "MLInfrastructure", targets: ["MLInfrastructure"]),
    ],
    dependencies: [
        // Foundation (Domain + Logging + Utilities)
        .package(path: "../Record-Foundation"),
        // Audio (test-only: CalendarAwareMeetingDetectorTests uses AudioSessionDetector)
        .package(path: "../Record-Audio"),
        // Transcription
        .package(url: "https://github.com/argmaxinc/WhisperKit.git", from: "1.0.0"),
        // Diarization
        .package(url: "https://github.com/FluidInference/FluidAudio.git", .upToNextMinor(from: "0.14.7")),
        // Storage
        .package(path: "../Prebuilts/duckdb-swift"),
        // MLX (shared inference runtime)
        .package(path: "../Prebuilts/mlx-swift"),
        .package(path: "../Prebuilts/mlx-swift-lm"),
        .package(path: "../Prebuilts/mlx-swift-structured"),
        // HuggingFace model hub
        .package(url: "https://github.com/huggingface/swift-huggingface", .upToNextMajor(from: "0.9.0")),
        .package(url: "https://github.com/huggingface/swift-transformers", .upToNextMajor(from: "1.3.3")),
    ],
    targets: [
        // MARK: - MLInfrastructure (ML/AI infrastructure — WhisperKit, MLX, diarization, storage)

        .target(
            name: "MLInfrastructure",
            dependencies: [
                .product(name: "Domain", package: "Record-Foundation"),
                .product(name: "Logging", package: "Record-Foundation"),
                .product(name: "Utilities", package: "Record-Foundation"),
                .product(name: "WhisperKit", package: "WhisperKit"),
                .product(name: "FluidAudio", package: "FluidAudio"),
                .product(name: "DuckDB", package: "duckdb-swift"),
                .product(name: "MLX", package: "mlx-swift"),
                .product(name: "MLXLLM", package: "mlx-swift-lm"),
                .product(name: "MLXLMCommon", package: "mlx-swift-lm"),
                .product(name: "MLXHuggingFace", package: "mlx-swift-lm"),
                .product(name: "MLXStructured", package: "mlx-swift-structured"),
                .product(name: "HuggingFace", package: "swift-huggingface"),
                .product(name: "Tokenizers", package: "swift-transformers"),
            ],
            path: "Sources/MLInfrastructure",
            resources: [.copy("Summarization/Prompts")],
            swiftSettings: sharedSwiftSettings
        ),

        // MARK: - Test Targets

        .testTarget(
            name: "MLInfrastructureTests",
            dependencies: [
                "MLInfrastructure",
                .product(name: "AudioInfrastructure", package: "Record-Audio"),
                .product(name: "Utilities", package: "Record-Foundation"),
            ],
            path: "Tests/Unit"
        ),
    ]
)

