import * as fs from 'fs';
import * as path from 'path';
import { execSync } from 'child_process';

const AGENTS_MD_PATH = 'AGENTS.md';
const MAX_LINES = 150;
const SECTION_EXTRACTION_THRESHOLD = 20;

interface AuditResult {
  passed: boolean;
  message: string;
}

class AgentsMdAuditor {
  private content: string = '';
  private lines: string[] = [];
  private results: AuditResult[] = [];

  constructor() {
    this.load();
  }

  private load() {
    if (fs.existsSync(AGENTS_MD_PATH)) {
      this.content = fs.readFileSync(AGENTS_MD_PATH, 'utf8');
      this.lines = this.content.split(/\r?\n/);
    }
  }

  audit() {
    this.results = [];
    this.checkExistence();
    if (this.content) {
      this.checkLength();
      this.checkSections();
      this.checkVagueness();
      this.checkSecurity();
      this.checkBrokenLinks();
      this.checkCommandAccuracy();
    }
    this.report();
    return this.results.every(r => r.passed);
  }

  private checkExistence() {
    if (!fs.existsSync(AGENTS_MD_PATH)) {
      this.results.push({ passed: false, message: 'AGENTS.md is missing from root.' });
    } else {
      this.results.push({ passed: true, message: 'AGENTS.md exists.' });
    }
  }

  private checkLength() {
    if (this.lines.length > MAX_LINES) {
      this.results.push({
        passed: false,
        message: `AGENTS.md is too long (${this.lines.length} lines). Recommended < ${MAX_LINES}.`,
      });
    } else {
      this.results.push({ passed: true, message: `Length is acceptable (${this.lines.length} lines).` });
    }
  }

  private checkSections() {
    const requiredSections = [
      'Environment',
      'Commands',
      'Conventions',
      'Testing',
      'Structure',
      'Permissions',
      'PR',
    ];

    for (const section of requiredSections) {
      const found = this.content.toLowerCase().includes(`## ${section.toLowerCase()}`);
      if (!found) {
        this.results.push({ passed: false, message: `Section "## ${section}" is missing.` });
      }
    }
  }

  private checkVagueness() {
    const vaguePatterns = [
      { pattern: /run tests/i, suggestion: 'Use explicit command like "swift test"' },
      { pattern: /check lint/i, suggestion: 'Use explicit command like "swiftlint"' },
      { pattern: /build project/i, suggestion: 'Use explicit command like "swift build"' },
    ];
    for (const p of vaguePatterns) {
      if (p.pattern.test(this.content)) {
        this.results.push({
          passed: false,
          message: `Found vague command: "${this.content.match(p.pattern)?.[0]}". ${p.suggestion}.`,
        });
      }
    }
  }

  private checkSecurity() {
    const secretPatterns = [/api[_-]?key/i, /secret[_-]?key/i, /password/i, /token/i];
    for (const line of this.lines) {
      for (const pattern of secretPatterns) {
        if (
          pattern.test(line) &&
          line.includes('=') &&
          !line.includes('.env') &&
          !line.includes('example')
        ) {
          this.results.push({ passed: false, message: `Potential hardcoded secret: ${line.trim()}` });
          break;
        }
      }
    }
  }

  // ── New: broken link detection ────────────────────────────────────────────
  // Finds markdown links [text](path) and backtick paths, verifies they exist.
  private checkBrokenLinks() {
    const mdLinkRe = /\[([^\]]+)\]\(([^)]+)\)/g;
    const backtickPathRe = /`((?:docs|scripts|Record-[A-Za-z]+)\/[^`]+)`/g;
    const broken: string[] = [];

    const check = (p: string) => {
      // Skip URLs and anchors
      if (p.startsWith('http') || p.startsWith('#')) return;
      if (!fs.existsSync(p)) broken.push(p);
    };

    let m: RegExpExecArray | null;
    while ((m = mdLinkRe.exec(this.content)) !== null) check(m[2]);
    while ((m = backtickPathRe.exec(this.content)) !== null) check(m[1]);

    if (broken.length > 0) {
      broken.forEach(p =>
        this.results.push({ passed: false, message: `Broken reference: "${p}" does not exist on disk.` })
      );
    } else {
      this.results.push({ passed: true, message: 'All file references resolve on disk.' });
    }
  }

  // ── New: command accuracy checks ─────────────────────────────────────────
  // Catches known wrong command forms that have historically crept in.
  private checkCommandAccuracy() {
    const badCommands: { pattern: RegExp; fix: string }[] = [
      {
        pattern: /`git nexus/,
        fix: '`gitnexus` (not `git nexus` — gitnexus is a standalone binary, not a git alias)',
      },
      {
        pattern: /`npx gitnexus/,
        fix: '`gitnexus` — installed globally via Homebrew, no npx needed',
      },
      {
        pattern: /\/tmp\//,
        fix: 'Never use /tmp — use .temp/ (cleared on reboot)',
      },
    ];

    for (const { pattern, fix } of badCommands) {
      if (pattern.test(this.content)) {
        this.results.push({ passed: false, message: `Incorrect command pattern matched: ${fix}` });
      }
    }
  }

  fix() {
    if (!fs.existsSync(AGENTS_MD_PATH)) {
      const template = `# AGENTS.md\n\n## Environment\n\n## Commands\n\n## Testing\n\n## Permissions\n`;
      fs.writeFileSync(AGENTS_MD_PATH, template);
      console.log('Created AGENTS.md template.');
      this.load();
    }

    if (this.lines.length > MAX_LINES) {
      console.log('Splitting AGENTS.md into modules for determinism...');
      const docsDir = 'docs/agents';
      if (!fs.existsSync(docsDir)) fs.mkdirSync(docsDir, { recursive: true });

      const sections: { title: string; lines: string[] }[] = [];
      let currentSection: { title: string; lines: string[] } | null = null;

      for (const line of this.lines) {
        if (line.startsWith('## ')) {
          if (currentSection) sections.push(currentSection);
          currentSection = { title: line.replace('## ', '').trim(), lines: [line] };
        } else if (currentSection) {
          currentSection.lines.push(line);
        } else if (line.trim() !== '' || sections.length === 0) {
          if (!sections.length) sections.push({ title: 'Header', lines: [line] });
          else sections[0].lines.push(line);
        }
      }
      if (currentSection) sections.push(currentSection);

      let newMainContent = '';
      for (const section of sections) {
        const isAlreadyReference = section.lines.some(
          l => l.includes(`See [${docsDir}`) || l.includes(`See [docs/agents`)
        );

        if (
          section.title === 'Header' ||
          section.lines.length < SECTION_EXTRACTION_THRESHOLD ||
          isAlreadyReference
        ) {
          newMainContent += section.lines.join('\n').trim() + '\n\n';
        } else {
          const fileName =
            section.title.toLowerCase().replace(/[^a-z0-9]/g, '-') + '.md';
          const filePath = path.join(docsDir, fileName);

          const fileContent = section.lines.join('\n').trim();
          fs.writeFileSync(filePath, fileContent);

          newMainContent += `## ${section.title}\n\nSee [${filePath}](${filePath}) for details.\n\n`;
          console.log(`Extracted section "${section.title}" to ${filePath}`);
        }
      }

      const finalized = newMainContent.trim() + '\n';
      if (finalized !== this.content) {
        fs.writeFileSync(AGENTS_MD_PATH, finalized);
        console.log('Updated AGENTS.md with deterministic references.');
      } else {
        console.log('AGENTS.md is already optimized.');
      }
    }

    this.load();
    this.audit();
  }

  private report() {
    console.log('--- AGENTS.md Audit Report ---');
    this.results.forEach(res => {
      console.log(`${res.passed ? '✅' : '❌'} ${res.message}`);
    });
    const failures = this.results.filter(r => !r.passed).length;
    if (failures === 0) {
      console.log('\nAll checks passed.');
    } else {
      console.log(`\n${failures} check(s) failed.`);
      process.exitCode = 1;
    }
  }
}

const auditor = new AgentsMdAuditor();
const args = process.argv.slice(2);

if (args.includes('--fix')) {
  auditor.fix();
} else {
  auditor.audit();
}

