      'Commands',
      'Conventions',
      'Testing',
      'Structure',
      'Permissions',
      'PR',
    ];

    for (const section of requiredSections) {
      const found = this.content.toLowerCase().includes(`## ${section.toLowerCase()}`);
      if (!found) {
        this.results.push({ passed: false, message: `Section "## ${section}" is missing.` });
      }
